('111.4.b.9.B',3,'Tia measures a bookshelf in centimeters. Pia measures the same bookshelf in meters. Who gets the greater number?','["Tia, because centimeters are shorter units", "Pia, because meters are shorter units", "They get the same number."]'::jsonb,0,'A shorter unit means you need more of them. Centimeters are shorter than meters.','original'),
('111.4.b.9.B',3,'Pia measures a hallway in inches. Max measures the same hallway in yards. Who gets the greater number?','["Max, because yards are shorter units", "Pia, because inches are shorter units", "They get the same number."]'::jsonb,1,'A shorter unit means you need more of them. Inches are shorter than yards.','original'),
('111.4.b.9.B',3,'Tia measures a bookshelf in feet. Eli measures the same bookshelf in yards. Who gets the greater number?','["Eli, because yards are shorter units", "They get the same number.", "Tia, because feet are shorter units"]'::jsonb,2,'A shorter unit means you need more of them. Feet are shorter than yards.','original'),
('111.4.b.9.C',3,'A frog sits at 4 on a number line and hops to 15. How far did the frog hop?','["10", "12", "11", "15"]'::jsonb,2,'The distance from 4 to 15 is 11.','original'),
('111.4.b.9.C',3,'A frog sits at 27 on a number line and hops to 28. How far did the frog hop?','["3", "55", "28", "1"]'::jsonb,3,'The distance from 27 to 28 is 1.','original'),
('111.4.b.9.C',3,'A bug starts at 25 on a number line and hops 6 spaces to the right. What number does it land on?','["31", "30", "6", "19"]'::jsonb,0,'25 + 6 = 31.','original'),
('111.4.b.9.C',3,'A bug starts at 20 on a number line and hops 5 spaces to the right. What number does it land on?','["24", "25", "15", "5"]'::jsonb,1,'20 + 5 = 25.','original'),
